import { HistoryStats } from "@/components/history/HistoryStats";
import { HistoryInfoRow } from "@/components/history/HistoryInfoRow";
import { HistoryToolbar } from "@/components/history/HistoryToolbar";
import { HistoryTable } from "@/components/history/HistoryTable";
import styles from "@/components/history/history.module.css";
import { RowActions } from "@/components/history/RowActions";
import Link from "next/link";
import { readEntitlements } from "@/lib/entitlements";
import { readFollowUps } from "@/lib/follow-ups";
import { Prisma } from "@/generated/prisma/client";
import { contactDeliveryState } from "@/lib/shortlist";
import { Suspense } from "react";
import { WorkspaceSkeleton } from "@/components/workspace-skeleton";
import { readCampaignProgress } from "@/lib/campaign-progress";
import { CampaignProgress } from "@/components/campaign-progress";
import { requireUser } from "@/lib/session";
import { db } from "@/lib/db";
import { readQuotaSnapshot } from "@/lib/quota-usage";
import { HistoryControls } from "@/components/history-controls";
import { DateTime } from "@/components/date-time";
import { Pagination } from "@/components/pagination";
import { pageNumber } from "@/lib/params";
export const metadata = { title: "History" };
async function HistoryContent({
  searchParams,
}: {
  searchParams: Promise<{
    status?: string;
    q?: string;
    page?: string;
    followUpPage?: string;
    campaign?: string;
  }>;
}) {
  const user = await requireUser();
  const params = await searchParams;
  const page = pageNumber(params.page);
  const q = (params.q ?? "").slice(0, 160);
  const status = ["QUEUED", "SENT", "FAILED", "REPLIED", "CANCELLED"].includes(
    params.status ?? "",
  )
    ? (params.status as "QUEUED" | "SENT" | "FAILED" | "REPLIED" | "CANCELLED")
    : undefined;
  const where = {
    campaign: { userId: user.id },
    historyDeletedAt: null,
    ...(status ? { status } : {}),
    ...(q
      ? {
          OR: [
            { recipientEmail: { contains: q, mode: "insensitive" as const } },
            { recipientName: { contains: q, mode: "insensitive" as const } },
            { recipientCompany: { contains: q, mode: "insensitive" as const } },
          ],
        }
      : {}),
  };
  const day = new Date();
  day.setUTCHours(0, 0, 0, 0);
  const sent = {
    campaign: { userId: user.id },
    historyDeletedAt: null,
    status: { in: ["SENT" as const, "REPLIED" as const] },
  };
  const [sends, total, today, allTime, replies, quota, queued] =
    await Promise.all([
      db.send.findMany({
        where,
        select: {
          id: true,
          contactId: true,
          recipientName: true,
          recipientEmail: true,
          recipientCompany: true,
          recipientRole: true,
          templateName: true,
          status: true,
          sentAt: true,
          error: true,
          replyMarkedAt: true,
          dispatchedAt: true,
          deliveryState: true,
        },
        orderBy: { createdAt: "desc" },
        take: 20,
        skip: (page - 1) * 20,
      }),
      db.send.count({ where }),
      db.send.count({ where: { ...sent, sentAt: { gte: day } } }),
      db.send.count({ where: sent }),
      db.send.count({
        where: {
          campaign: { userId: user.id },
          historyDeletedAt: null,
          status: "REPLIED",
        },
      }),
      readQuotaSnapshot(user.id),
      db.send.count({
        where: {
          campaign: { userId: user.id },
          historyDeletedAt: null,
          status: "QUEUED",
        },
      }),
    ]);
  const followUpPage = pageNumber(params.followUpPage);
  const access = await readEntitlements(user.id);
  const due = await readFollowUps(user.id, user.followUpDays, followUpPage);
  const contactIds = [
    ...new Set([
      ...sends.map((s) => s.contactId),
      ...due.contacts.map((c) => c.id),
    ]),
  ];
  const contactStates = contactIds.length
    ? await db.$queryRaw<
        {
          id: string;
          email: string;
          archivedAt: Date | null;
          shortlistRemovedAt: Date | null;
          blocked: boolean;
          previouslySent: boolean;
          followUp: boolean;
        }[]
      >(Prisma.sql`
        SELECT c.id, c.email, c."archivedAt", c."shortlistRemovedAt",
          state.blocked, state."previouslySent", state."followUp"
        FROM "Contact" c CROSS JOIN LATERAL (${contactDeliveryState}) state
        WHERE c."userId" = ${user.id} AND c.id IN (${Prisma.join(contactIds)})
      `)
    : [];
  const states = new Map(contactStates.map((c) => [c.id, c]));
  function shortlistProps(contactId: string) {
    const contact = states.get(contactId);
    return {
      inShortlist:
        !!contact &&
        !contact.shortlistRemovedAt &&
        (contact.blocked || !contact.previouslySent || contact.followUp),
      blocked: contact?.blocked ?? false,
      active: !!contact && !contact.archivedAt,
    };
  }
  // Initial visits show only the live queue; completion belongs to client visit state.
  const progress = await readCampaignProgress(user);
  return (
    <div
      className={`${styles.root} text-[var(--h-text)] [font-family:var(--font-plus-jakarta),_sans-serif] history-page`}
    >
      <HistoryControls
        hasQueued={queued > 0}
        autoRefresh={!progress || (!progress.queued && !progress.review)}
      />
      <header className="workspace-screen-heading [margin:12px_0_28px]">
        <p
          className={`${styles.eyebrow} [font:500_11.5px_var(--font-jetbrains),_monospace] tracking-[0.14em] uppercase text-[var(--h-purple)]`}
        >
          Every introduction, in view
        </p>
        <h1 className="mt-2 text-[clamp(30px,_4.6vw,_46px)] font-extrabold leading-[1.08] tracking-[-0.04em]">
          History
        </h1>
        <p className="text-[var(--h-muted)] mt-2">
          Follow your messages from the queue to a new conversation.
        </p>
      </header>
      <HistoryStats
        today={today}
        queued={queued}
        totalSent={allTime}
        replies={replies}
        source={quota}
      />
      <HistoryInfoRow />
      <CampaignProgress data={progress} />
      <HistoryToolbar q={q} status={status ?? ""} campaign={params.campaign} />
      <HistoryTable
        messages={sends}
        filtered={!!q || !!status || page > 1}
        shortlistStates={Object.fromEntries(
          sends.map((s) => [s.contactId, shortlistProps(s.contactId)]),
        )}
      />
      <div className={styles.pagination}>
        <Pagination
          path="/history"
          page={page}
          total={total}
          query={{ q, status: status ?? "", campaign: params.campaign ?? "" }}
        />
      </div>
      <div className="mt-6">
        {access.features.followUpReminders && user.followUpDays > 0 && (
          <section
            className="panel history-follow-ups grid gap-3 py-5 px-6 mb-6"
            aria-label="Follow-ups due"
          >
            <h2 className="section-label [font:600_11px/1.5_ui-monospace,_monospace] tracking-[0.14em] uppercase text-body">
              Follow-ups due · {due.total}
            </h2>
            <p className="text-sm text-body">
              {due.contacts.length
                ? `No reply marked after ${user.followUpDays} days. Review in Compose before sending.`
                : "No follow-ups due on this page."}
            </p>
            {due.contacts.map((c) => (
              <div
                key={c.id}
                className="flex flex-wrap items-center justify-between gap-3 border-t border-dotted border-separator pt-3"
              >
                <div className="min-w-0">
                  <p className="break-words">{c.name}</p>
                  <p className="break-all text-xs text-body">{c.email}</p>
                  <p className="text-xs text-body">
                    Sent <DateTime value={c.sentAt.toISOString()} />
                  </p>
                </div>
                <div className="history-actions flex flex-col items-end gap-2">
                  <RowActions
                    id={c.sendId}
                    status="SENT"
                    shortlist={shortlistProps(c.id)}
                  />
                </div>
              </div>
            ))}
            {due.total > 20 && (
              <nav
                aria-label="Follow-up pagination"
                className="flex flex-wrap items-center gap-4 text-sm"
              >
                <span>
                  Page {followUpPage} of{" "}
                  {Math.max(1, Math.ceil(due.total / 20))}
                </span>
                {followUpPage > 1 && (
                  <Link
                    className="inline-flex min-h-11 items-center text-link"
                    href={`/history?${new URLSearchParams({ q, status: status ?? "", page: String(page), followUpPage: String(followUpPage - 1) })}`}
                  >
                    Previous follow-ups
                  </Link>
                )}
                {followUpPage * 20 < due.total && (
                  <Link
                    className="inline-flex min-h-11 items-center text-link"
                    href={`/history?${new URLSearchParams({ q, status: status ?? "", page: String(page), followUpPage: String(followUpPage + 1) })}`}
                  >
                    Next follow-ups
                  </Link>
                )}
              </nav>
            )}
          </section>
        )}
      </div>
    </div>
  );
}

export default async function History(
  props: Parameters<typeof HistoryContent>[0],
) {
  const params = await props.searchParams;
  return (
    <Suspense
      fallback={
        <WorkspaceSkeleton page="history" showProgress={!!params.campaign} />
      }
    >
      <HistoryContent {...props} />
    </Suspense>
  );
}
